/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to Discounts and add entry to Price Change tracking table 
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeEvent))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, DiscountDisabled))]
public class METPriceChangeEventDiscountDisabled extends METPriceChangeEvent
{
    RetailPeriodicDiscount  retailPeriodicDiscount;
    RecordInsertList        priceChangeTrackingDetailList;

}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void initInstance(Common _common, SysAppCRUDOperation _crud)
{
    this.setInternals(_Common, _crud);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void setInternals(Common _common, SysAppCRUDOperation _crud)
{
    super(_common, _crud);
    retailPeriodicDiscount = _common as retailPeriodicDiscount;
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::DiscountDisabled;
}

/// <summary>
/// Get the Opposite Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeTypeOpposite()
{
    return METPriceChangeType::DiscountEnabled;
}

/// <summary>
/// Process the base record that triggered the change and create Price Change Track record
/// </summary>
public void process()
{
    if(retailPeriodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer)
    {
        this.processSingle(qtyOne);
    }
    else if (retailPeriodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Multibuy)
    {
        this.processQuantity();
    }
}

    /// <summary>
    /// Process the base record that triggered the change and create Price Change Track record
    /// </summary>
    /// <param name = "_fromQty">From Quantity</param>
    public void processSingle(RetailQtyLowest _fromQty)
    {
        FromDate                    fromDate;
        RetailQtyLowest             fromQty;
        boolean                     skipCreation;
        Counter                     insertCount;

        fromDate = this.getFromDate(retailPeriodicDiscount.ValidFrom);
        fromQty = this.getFromQty(_fromQty);

        skipCreation = this.preProcess(fromDate, fromQty, sourceCrud);

        if(!SkipCreation)
        {
            ttsbegin;
            this.processTrans(fromDate, fromQty);
            priceChangeTracking.insert();
            ttscommit;

            ttsbegin;
            priceChangeTrackingDetailList = new RecordInsertList(tableNum(METPriceChangeTrackingDetail));
            this.processDetail();
            insertCount = priceChangeTrackingDetailList.insertDatabase();

            if(!insertCount) //no detail record was created
            {
                priceChangeTracking.selectForUpdate(true);
                priceChangeTracking.delete();
            }
            ttscommit;
        }
    }

    /// <summary>
    /// Process the base record that triggered the change and create Price Change Track record
    /// </summary>
    public void processQuantity()
    {
        RetailMultibuyDiscountLine  retailMultibuyDiscountLine;

        while select retailMultibuyDiscountLine
            where   retailMultibuyDiscountLine.multibuyId == retailPeriodicDiscount.OfferId
        {
            this.processSingle(retailMultibuyDiscountLine.qtyLowest);
        }
    }

/// <summary>
/// Process the base record that triggered the change and create Price Change Track record
/// </summary>
/// <param name = "_fromDate">From Date</param>
/// <param name = "_fromQty">From Quantity</param>
public void processTrans(FromDate _fromDate, RetailQtyLowest _fromQty)
{
    priceChangeTracking.clear();
    this.setCommonValues(retailPeriodicDiscount);
    priceChangeTracking.pricingRuleHeader       = retailPeriodicDiscount.HeaderPricingRule;
    priceChangeTracking.DiscountCode            = retailPeriodicDiscount.offerId;
    priceChangeTracking.ToDate                  = retailPeriodicDiscount.ValidTo;
    priceChangeTracking.Activation              = NoYes::No;
    priceChangeTracking.QuantityAmountFrom      = _fromQty;
    priceChangeTracking.FromDate                = _fromDate;
}

    /// <summary>
    /// Create detail records related to the base record that triggered the change. Specific to Disabled scenario.
    /// </summary>
    public void processDetail()
    {
        RetailPeriodicDiscountLine  retailPeriodicDiscountLine;
        InventDim                   inventDim;
        Query               custPreviewQuery;
        Query               productPreviewQuery;
        GUPPricingRuleCopy  pricingRuleCopyCustHeader, pricingRuleCopy;
        InventSiteId        inventSiteId;
        Set                 custAccountSet, inventItemSet;

        METPriceChangeTrack priceChangeTrack = METPriceChangeTrackFactory::newFromPriceChangeType(priceChangeTracking.ChangeType);
        priceChangeTrack.initInstance(priceChangeTracking, false);

        pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(priceChangeTracking.pricingRuleHeader));
        
        while select RecId, OfferId, LinePricingRule, InventDimId, UnitOfMeasure, LineNum
            from    retailPeriodicDiscountLine
            where   retailPeriodicDiscountLine.OfferId == retailPeriodicDiscount.OfferId
            exists join InventDim
            where   InventDim.InventDimId               == retailPeriodicDiscountLine.InventDimId
            &&      InventDim.InventSiteId
        {
            pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(retailPeriodicDiscountLine.LinePricingRule));
        
            inventSiteId = InventDim::find(retailPeriodicDiscountLine.InventDimId).InventSiteId;

            custPreviewQuery = priceChangeTrack.buildCustQuery(pricingRuleCopyCustHeader, InventSiteId, retailPeriodicDiscount.HeaderPricingGroupCode);
            custAccountSet = priceChangeTrack.buildCustValues(custPreviewQuery, pricingRuleCopyCustHeader);
            
            productPreviewQuery = priceChangeTrack.buildProductQueryBase(pricingRuleCopy);
            inventItemSet = priceChangeTrack.buildItemValues(productPreviewQuery, pricingRuleCopy);

            this.processDetailQuantity(custAccountSet, inventItemSet, retailPeriodicDiscountLine);
        }
    }

    /// <summary>
    /// Create detail records related to the base record that triggered the change. Specific to Disabled scenario.
    /// </summary>
    /// <param name = "_custAccountSet">Customer Accounts</param>
    /// <param name = "_inventItemSet">Items</param>
    /// <param name = "_retailPeriodicDiscountLine">Discount line</param>
    public void processDetailQuantity(Set _custAccountSet, Set _inventItemSet, RetailPeriodicDiscountLine  _retailPeriodicDiscountLine)
    {
        SetEnumerator       custAccountEnumerator, inventItemEnumerator;
        AccountNum          custAccount;
        ItemId              inventItem;
        InventSiteId        inventSiteId;
        METUnitOfMeasure    unitId;
        Set                 custAccountSet, inventItemSet;

        custAccountSet  = _custAccountSet;
        inventItemSet   = _inventItemSet;

        if(custAccountSet && inventItemSet) //must have atleast 1 customer and 1 Item to proceed
        {
            custAccountEnumerator = custAccountSet.getEnumerator();
            while(custAccountEnumerator.moveNext())
            {
                custAccount = custAccountEnumerator.current();
                this.processDetailTrans(METPriceTrackDetailType::Customer, custAccount, _retailPeriodicDiscountLine.LineNum);
            }

            inventItemEnumerator = inventItemSet.getEnumerator();
            while(inventItemEnumerator.moveNext())
            {
                inventItem  = inventItemEnumerator.current();
                this.processDetailTrans(METPriceTrackDetailType::Product, inventItem, _retailPeriodicDiscountLine.LineNum);
            }

            if(_retailPeriodicDiscountLine.InventDimId)
            {
                inventSiteId = InventDim::find(_retailPeriodicDiscountLine.InventDimId).InventSiteId;
                this.processDetailTrans(METPriceTrackDetailType::SiteId, inventSiteId, _retailPeriodicDiscountLine.LineNum);
            }

            if(_retailPeriodicDiscountLine.UnitOfMeasure)
            {
                unitId = UnitOfMeasure::find(_retailPeriodicDiscountLine.UnitOfMeasure).Symbol;
                this.processDetailTrans(METPriceTrackDetailType::UnitId, unitId, _retailPeriodicDiscountLine.LineNum);
            }
        }

    }

    /// <summary>
    /// Create detail records related to the base record that triggered the change. Specific to Disabled scenario.
    /// </summary>
    /// <param name = "_priceTrackDetailType">Price change type</param>
    /// <param name = "_priceTrackDetailCode">Price change code</param>
    /// <param name = "_lineNumber">Line number</param>
    public void processDetailTrans(METPriceTrackDetailType _priceTrackDetailType, METPriceTrackDetailCode _priceTrackDetailCode, LineNumber _lineNumber)
    {
        METPriceChangeTrackingDetail    priceChangeTrackingDetail;

        priceChangeTrackingDetail.clear();
        priceChangeTrackingDetail.initValue();
        priceChangeTrackingDetail.TrackingId        = priceChangeTracking.TrackingId;
        priceChangeTrackingDetail.ChangeType        = priceChangeTracking.ChangeType;
        priceChangeTrackingDetail.LineNumber          = _lineNumber;
        priceChangeTrackingDetail.PriceTrackDetailType = _priceTrackDetailType;
        priceChangeTrackingDetail.PriceTrackDetailCode = _priceTrackDetailCode;

        priceChangeTrackingDetailList.add(priceChangeTrackingDetail);
    }

    /// <summary>
    /// Pre Process logic
    /// In some scenarios we may delete an existing record and not create the current one.
    /// </summary>
    /// <param name = "_fromDate">from date</param>
    /// <param name = "_fromQty">qty from</param>
    /// <param name = "_crud">CRUD operation</param>
    /// <returns>Success</returns>
    public boolean preProcess(FromDate _fromDate, RetailQtyLowest _fromQty, SysAppCRUDOperation _crud)
    {
        boolean ret = false;
        METPriceChangeTracking      priceChangeTrackingLoc;

        //As this is a Disabled action, remove any existing Enabled
        ttsbegin;
            
        //should only be one record. Use while loop so that ret variable can be set
        while select forupdate priceChangeTrackingLoc
            where   priceChangeTrackingLoc.DiscountCode    == retailPeriodicDiscount.OfferId
            &&      priceChangeTrackingLoc.FromDate        == _fromDate
            &&      priceChangeTrackingLoc.QuantityAmountFrom  == _fromQty
            &&      priceChangeTrackingLoc.ChangeType      == this.getPriceChangeTypeOpposite()
        {
            priceChangeTrackingLoc.delete();
                
            ret = true;
        }

        ttscommit;
        
        return ret;
    }
